insert into level_blocks (id,era,level_from,level_to,theme,grammar) values
  (0,1,1,5,'Saudações, títulos Sir/Ma''am, verbo to be, apresentações, cortesia e pontualidade','Verbo to be (presente), cumprimentos, pronomes pessoais'),
  (1,1,6,10,'O lar, cômodos, parentesco, refeições em família, gratidão à mesa e hospitalidade','This is / these are, possessivos, there is / there are'),
  (2,1,11,15,'Profissões, números, horas, rotina produtiva, Simple Present e ética do trabalho','Simple Present, números e horas, advérbios de frequência'),
  (3,1,16,20,'Direções, cidade, instituições, leis, símbolos nacionais, dever cívico e história básica','Imperativo, preposições de lugar, can / must'),
  (4,1,21,26,'Cores, animais, natureza, infância respeitosa, obediência aos pais e rotina escolar','Adjetivos, there is / there are, can, imperativo gentil'),
  (5,2,27,32,'Passado simples, memórias de família, domingos em casa e relatos de esforço','Simple Past (regulares e irregulares), going to'),
  (6,2,33,38,'Virtudes cardeais (prudence, justice, fortitude, temperance), paciência e autodomínio','Simple Past contínuo, conjunções because / so / but'),
  (7,2,39,44,'Orçamento doméstico, poupança, compra consciente, planejamento e futuro','Futuro com going to e will, quantificadores (much, many)'),
  (8,2,45,52,'Vizinhança, hospitalidade, viagens em família, comparativos e superlativos, preposições de tempo e lugar, regras de convivência','Comparativos, superlativos, preposições de tempo e lugar'),
  (9,3,53,59,'Livre iniciativa, contratos, propriedade privada, lucro honesto, negociação e liderança servidora','Present Perfect, modais de negociação (could, would)'),
  (10,3,60,66,'Marcos da civilização ocidental, biografias, causas e consequências','Present Perfect vs. Simple Past, conectivos de causa e consequência'),
  (11,3,67,72,'Cidadania ativa, responsabilidade legal, liberdade e ordem','First & Second Conditionals, modais de dever (must, should, ought to)'),
  (12,3,73,78,'Gestão de recursos, agronegócio e tecnologia no campo, resiliência e planejamento de longo prazo','Futuro contínuo, voz ativa em relatórios, conectivos de planejamento'),
  (13,4,79,85,'Argumentação jurídica e cívica, defesa das liberdades individuais','Voz passiva, Reported Speech'),
  (14,4,86,92,'Engenharia, padrões de excelência e gestão de projetos complexos','Third Conditional, linguagem técnica de precisão'),
  (15,4,93,98,'Estratégia empresarial, cadeias produtivas, inovação responsável e mediação de acordos','Conectivos formais, modais de possibilidade e dedução'),
  (16,4,99,104,'Leitura crítica de textos clássicos (O Peregrino, fábulas, Provérbios e Salmos), conectivos formais e tradição familiar','Conectivos formais, linguagem literária e figurada'),
  (17,5,105,111,'Leitura e análise de ideias clássicas (C. S. Lewis, G. K. Chesterton, Edmund Burke) e textos sapienciais','Estruturas complexas de argumentação, nominalização'),
  (18,5,112,118,'Oratória pública, retórica persuasiva, tom formal vs. diplomático','Subjuntivo formal, inversões enfáticas'),
  (19,5,119,125,'Negociações internacionais de alto nível, governança, expressões idiomáticas cultas e análise de cenários','Expressões idiomáticas cultas, hedging, condicionais mistas'),
  (20,5,126,130,'Síntese geral do currículo, apresentações sem suporte, domínio fonético avançado e legado familiar','Revisão integrada de todo o currículo');
