insert into pronunciation_tips (id,title,words,pattern,tip_pt) values
  ('th_voiceless','Som de TH (sem voz)','["think","three","truth","thank","thanks","thing","both","path","month","faith"]'::jsonb,'^th|th$','Para o TH de “truth”, coloque a ponta da língua levemente entre os dentes e sopre, sem som de F ou T.'),
  ('th_voiced','Som de TH (com voz)','["the","this","that","these","they","them","mother","father","with","brother","other"]'::jsonb,'th','Língua entre os dentes, como no TH anterior, mas faça a garganta vibrar. Não troque por D nem Z.'),
  ('final_consonant','Consoante final seca','["work","walk","book","word","good","help","night","great","start","meet","at"]'::jsonb,'[kdtpb]$','Não adicione um “i” no final de “work”. Corte o som no K, no D ou no T, sem soltar vogal.'),
  ('s_cluster','S + consoante no início','["school","street","student","state","speak","special","story","study","sport"]'::jsonb,'^s[ptkcm]|^str|^spl|^scr','Não coloque um “e” antes do S: diga “skool”, não “iskool”. Comece direto no S.'),
  ('h_aspirated','Som de H aspirado','["house","home","have","his","her","hello","how","help","husband","happy","history"]'::jsonb,'^h','O H em inglês é um sopro suave, como se você embaçasse um vidro. Não é o “rr” do português.'),
  ('ae_sound','O “a” aberto de Ma''am','["ma''am","man","that","have","happy","back","plan","stand","family","can"]'::jsonb,'ma''?am|^[^aeiou]*a[^aeiouyrw]+$','Em “Ma''am” e “man”, o A é bem aberto, entre o “é” e o “á” do português. Abra a boca como para dizer “é”, com a mandíbula mais baixa.'),
  ('r_sound','O R americano','["right","work","red","free","great","correct","are","for","very","morning","truth","grow"]'::jsonb,'r','Enrole a língua para trás sem encostar no céu da boca e sem vibrar. Não use o “rr” nem o “h” do português.'),
  ('ed_ending','Final -ed','["worked","asked","needed","wanted","stopped","helped","planted","earned","returned"]'::jsonb,'ed$','O -ed tem três sons: /t/ depois de som surdo (worked), /d/ depois de som sonoro (earned) e /id/ depois de T ou D (wanted).'),
  ('short_i','I curto e I longo','["ship","sheep","live","leave","fill","feel","it","this","in","is"]'::jsonb,'^i|^sh','“Ship” tem som curto e relaxado; “sheep” é longo e tenso. Não alongue o I curto como se fosse “i” do português.'),
  ('schwa','Vogal fraca (schwa)','["about","family","again","today","banana","the","a","of","to"]'::jsonb,'^a|^o','Vogais sem acento viram um “ã” bem curto e relaxado: “a-BOUT”, “FAM-ly”. Acente só a sílaba forte.'),
  ('w_sound','Som de W','["we","work","would","water","well","will","welcome","what","with","one","away"]'::jsonb,'^w','Arredonde os lábios como para assoprar uma vela, depois abra. É um “u” curto, sem o V do português.'),
  ('j_dg','Som de J e DG','["job","judge","just","jump","large","age","knowledge","engineer"]'::jsonb,'^j|dg|ge$','Comece com língua no céu da boca, como “dj”: “djob”, não “jóbi”. Lábios levemente projetados.'),
  ('tion','Final -tion','["nation","information","education","question","tradition","station"]'::jsonb,'tion$','Pronuncie “shun”: na-SHUN, não “ta-ção”. A sílaba forte vem antes do -tion.'),
  ('silent','Letras mudas','["Wednesday","listen","honest","hour","honor","half","know","knowledge","building"]'::jsonb,'^kn|^wr|^hon|^hour','Algumas letras não soam: “honest” começa com O, “listen” não tem T, “know” não tem K.'),
  ('final_l','L final','["all","well","tell","real","family","will","people","little","help"]'::jsonb,'l$','Encoste a ponta da língua atrás dos dentes de cima e segure. Não transforme em “u” como no português (“Brasiu”).'),
  ('final_nasal','M e N finais','["from","time","them","come","name","men","in","on","an","can"]'::jsonb,'[mn]$','Feche bem os lábios no M final e encoste a língua no N final. Não nasalize a vogal anterior como em “tão”.'),
  ('z_between','S entre vogais','["is","easy","has","as","was","these","please","busy","those","music"]'::jsonb,'s$|^e?asy','O S de “is”, “easy” e “has” soa como Z. No fim de palavras como “is” e “was”, vibre a garganta.'),
  ('generic','Ouça e imite','[]'::jsonb,'^$','Ouça a palavra devagar (🐢), repita em voz alta e grave de novo. Abra bem a boca nas vogais fortes e articule cada consoante até o fim.');
insert into wisdom_quotes (id,kind,en,pt,source) values
  ('w01','bible','A good name is to be chosen rather than great riches.','Mais vale o bom nome do que grandes riquezas.','Provérbios 22:1'),
  ('w02','bible','A soft answer turns away wrath.','A resposta branda desvia o furor.','Provérbios 15:1'),
  ('w03','bible','A slack hand causes poverty, but the hand of the diligent makes rich.','A mão negligente empobrece, mas a mão diligente enriquece.','Provérbios 10:4'),
  ('w04','bible','Honor your father and your mother.','Honra teu pai e tua mãe.','Êxodo 20:12'),
  ('w05','bible','The fear of the Lord is the beginning of knowledge.','O temor do Senhor é o princípio do conhecimento.','Provérbios 1:7'),
  ('w06','bible','Train up a child in the way he should go.','Instrui a criança no caminho em que deve andar.','Provérbios 22:6'),
  ('w07','bible','Trust in the Lord with all your heart.','Confia no Senhor de todo o teu coração.','Provérbios 3:5'),
  ('w08','bible','Righteousness exalts a nation.','A justiça engrandece uma nação.','Provérbios 14:34'),
  ('w09','bible','Iron sharpens iron, and one man sharpens another.','O ferro com o ferro se afia, e um homem afia o outro.','Provérbios 27:17'),
  ('w10','bible','Go to the ant, O sluggard; consider her ways, and be wise.','Vai ter com a formiga, preguiçoso; observa seus caminhos e sê sábio.','Provérbios 6:6'),
  ('w11','bible','The Lord is my shepherd; I shall not want.','O Senhor é o meu pastor; nada me faltará.','Salmo 23:1'),
  ('w12','bible','Pride goes before destruction, and a haughty spirit before a fall.','A soberba precede a ruína, e o espírito altivo precede a queda.','Provérbios 16:18'),
  ('w13','bible','Commit your work to the Lord, and your plans will be established.','Confia ao Senhor as tuas obras, e teus planos se firmarão.','Provérbios 16:3'),
  ('w14','classic','Courage is not simply one of the virtues, but the form of every virtue at the testing point.','A coragem não é apenas uma das virtudes, mas a forma de toda virtude no momento da prova.','C. S. Lewis, The Screwtape Letters'),
  ('w15','classic','The Christian ideal has not been tried and found wanting. It has been found difficult and left untried.','O ideal cristão não foi tentado e achado insuficiente. Foi achado difícil e deixado sem tentativa.','G. K. Chesterton, What''s Wrong with the World'),
  ('w16','classic','Tradition means giving a vote to the most obscure of all classes, our ancestors.','Tradição significa dar voto à mais obscura de todas as classes: nossos antepassados.','G. K. Chesterton, Orthodoxy'),
  ('w17','classic','Society is a partnership between those who are living, those who are dead, and those who are to be born.','A sociedade é uma parceria entre os que vivem, os que morreram e os que ainda hão de nascer.','Edmund Burke, Reflections on the Revolution in France'),
  ('w18','classic','Do not waste time bothering whether you love your neighbor; act as if you did.','Não perca tempo se perguntando se ama o seu próximo; aja como se amasse.','C. S. Lewis, Mere Christianity'),
  ('w19','bible','Give respect to those who deserve respect, and honor to those who deserve honor.','Dai respeito a quem merece respeito, e honra a quem merece honra.','Romanos 13:7 (adaptado)');
insert into readings (id,title,author,level,cost_talents,words,source_note) values
  ('r1','Salmo 23 (trecho)','King James Version',1,0,'[["The Lord","O Senhor"],["is","é"],["my","meu"],["shepherd","pastor"],["I shall not want","nada me faltará"],["He makes me","Ele me faz"],["lie down","deitar"],["in green pastures","em verdes pastos"],["He leads me","Ele me conduz"],["beside","ao lado de"],["still waters","águas tranquilas"]]'::jsonb,'Salmo 23:1-2, em inglês americano atual.'),
  ('r2','A Formiga Diligente','Provérbios 6 e fábula clássica (adaptação)',1,20,'[["In summer,","No verão,"],["the ant","a formiga"],["works","trabalha"],["every day.","todos os dias."],["She","Ela"],["gathers","recolhe"],["food","comida"],["for the winter.","para o inverno."],["The grasshopper","O gafanhoto"],["only","apenas"],["sings","canta"],["and plays.","e brinca."],["When winter comes,","Quando o inverno chega,"],["the ant","a formiga"],["has bread,","tem pão,"],["but he has none.","mas ele não tem nenhum."]]'::jsonb,'Adaptação didática de fábula de Esopo; ver Provérbios 6:6-8.'),
  ('r3','O Peregrino (abertura)','John Bunyan, The Pilgrim''s Progress',2,40,'[["As I walked","Enquanto eu caminhava"],["through the wilderness","pelo deserto"],["of this world,","deste mundo,"],["I lighted on","deparei-me com"],["a certain place","um certo lugar"],["where was a den,","onde havia uma cova,"],["and I laid me down","e me deitei"],["in that place","naquele lugar"],["to sleep;","para dormir;"],["and, as I slept,","e, enquanto dormia,"],["I dreamed a dream.","tive um sonho."]]'::jsonb,'Domínio público (1678). Texto original, grafia modernizada.');
insert into levels (id,number,era,block_id,title,status,origin,grammar,wisdom_id,pnl) values
  ('L001',1,1,0,'Saudações e Títulos de Respeito','available','autoral','Cumprimentos por período do dia; Sir / Ma''am; verbo to be com I, you e we (I am, you are, we are).','w19','{"identity":"Você é o tipo de pessoa que trata cada um com respeito — e o respeito começa no primeiro “Good morning”.","presupposition":"Quando você cumprimentar alguém em inglês amanhã, as palavras vão sair naturais, como se sempre tivessem sido suas.","futurePacing":["Feche os olhos por um instante e respire fundo.","Imagine-se chegando pontualmente a um encontro importante e dizendo, com voz firme: “Good evening, Sir.”","Veja o sorriso de quem se sente respeitado por você e ouça a resposta: “Thank you. You are on time.”","Sinta a segurança de quem deu o primeiro passo do seu legado em inglês."]}'::jsonb),
  ('L002',2,1,0,'Apresentações, Verbo to be e Cortesia','available','adaptado','Cumprimentos formais, apresentações respeitosas, títulos de tratamento, verbo to be no presente.','w02','{"identity":"Você é alguém que termina o que começa. É assim que se forma o caráter.","presupposition":"Quando você concluir o Checkpoint de Honra deste nível, “Apresentações, Verbo to be e Cortesia” vai fazer parte do seu inglês de todos os dias.","futurePacing":["Feche os olhos por um instante e respire fundo.","Imagine-se usando o que aprendeu em “Apresentações, Verbo to be e Cortesia” numa conversa real, com calma e segurança.","Ouça a sua própria voz, firme e clara, e veja o respeito no olhar de quem escuta.","Sinta a satisfação de quem constrói o próprio legado, um nível de cada vez."]}'::jsonb),
  ('L003',3,1,0,'Ele, Ela, Eles: o Verbo to be','planned',null,null,null,null),
