insert into level_lessons (id,level_id,slot,title,objective,intro,dialogue_ref,steps) values
  ('L001-01','L001',1,'Bom dia, boa tarde, boa noite','Cumprimentar em cada período do dia e usar Sir e Ma''am.','Quando você concluir estes 3 minutos, vai saber cumprimentar qualquer pessoa, em qualquer hora do dia.',null,'[{"kind":"learn","ref":"c1"},{"kind":"learn","ref":"c2"},{"kind":"learn","ref":"c3"},{"kind":"learn","ref":"c4"},{"kind":"context","q":"São 9h da manhã. Como você cumprimenta?","options":["Good morning","Good afternoon","Good night"],"answer":"Good morning","speak":"Good morning","explain":"Até o meio-dia, use “Good morning”."},{"kind":"learn","ref":"c7"},{"kind":"learn","ref":"c8"},{"kind":"choose","ref":"c8","dir":"pt-en"},{"kind":"listen","ref":"c3"},{"kind":"context","q":"São 22h e você está indo embora. O que você diz?","options":["Good night","Good evening","Good afternoon"],"answer":"Good night","speak":"Good night","explain":"Na despedida à noite, use “Good night”. “Good evening” é para quando você chega."}]'::jsonb),
  ('L001-02','L001',2,'I am, you are, we are','Usar o verbo to be com I, you e we.','Quando você terminar esta lição, vai perceber que o inglês usa um só verbo para “ser” e “estar” — e isso simplifica tudo.',null,'[{"kind":"note","title":"O verbo to be","body":"I am = eu sou / eu estou\nYou are = você é / você está\nWe are = nós somos / nós estamos\nEm inglês, o mesmo verbo serve para “ser” e para “estar”.","examples":["s4","s12","s10"]},{"kind":"learn","ref":"c9"},{"kind":"learn","ref":"c10"},{"kind":"learn","ref":"c13"},{"kind":"learn","ref":"c12"},{"kind":"fill","ref":"s4","blank":"am","options":["am","are","is"],"explain":"Com “I”, use “am”: I am fine."},{"kind":"fill","ref":"s12","blank":"are","options":["are","am","is"],"explain":"Com “you”, use “are”: you are."},{"kind":"fill","ref":"s10","blank":"are","options":["are","is","am"],"explain":"Com “we”, use “are”: we are."},{"kind":"bank","ref":"s3","dir":"pt-en"}]'::jsonb),
  ('L001-03','L001',3,'Encontro na praça','Entender uma conversa curta só pelo ouvido.','Quando você ouvir a conversa pela segunda vez, vai entender muito mais do que imagina.',null,'[{"kind":"questions"},{"kind":"dictation","ref":"s1"},{"kind":"dictation","ref":"s9"}]'::jsonb),
  ('L001-04','L001',4,'O concerto de Helena','Acompanhar a conversa dos dois casais e responder no momento certo.','Quando você acompanhar a conversa palavra por palavra, vai sentir o ritmo natural do inglês.','d1','[{"kind":"learn","ref":"c5"},{"kind":"learn","ref":"c6"},{"kind":"learn","ref":"c11"},{"kind":"next","ref":"d1.5"},{"kind":"bank","ref":"d1.2","dir":"pt-en"},{"kind":"listen","ref":"d1.0"},{"kind":"choose","ref":"c11","dir":"en-pt"}]'::jsonb),
  ('L001-05','L001',5,'Fale com clareza','Pronunciar os cumprimentos com o TH, o H aspirado e as consoantes finais corretos.','Quando você ouvir a sua própria voz dizendo “Good morning, Ma''am”, vai perceber o quanto já avançou.',null,'[{"kind":"note","title":"Micro-dica de pronúncia","body":"Antes de falar, ouça devagar (🐢) e repare: o TH de “thank” sai com a língua entre os dentes; o H de “hello” e “how” é um sopro; e “good” termina seco no D, sem “i” no final.","tip":"th_voiceless"},{"kind":"speak","ref":"c1"},{"kind":"speak","ref":"s1"},{"kind":"speak","ref":"c9"},{"kind":"speak","ref":"s4"},{"kind":"speak","ref":"s6"},{"kind":"roleplay"}]'::jsonb),
  ('L001-06','L001',6,'Escreva sem medo','Traduzir do português para o inglês com cada vez menos dicas.','Quando você escrever a última frase sem nenhuma dica, vai saber que o inglês já é seu.',null,'[{"kind":"bank","ref":"s1","dir":"pt-en"},{"kind":"bank","ref":"s5","dir":"en-pt"},{"kind":"write","ref":"s9","hint":"first"},{"kind":"write","ref":"s3","hint":"first"},{"kind":"write","ref":"s7","hint":"none"},{"kind":"write","ref":"s11","hint":"none"}]'::jsonb),
  ('L001-07','L001',7,'Tudo junto','Misturar tudo o que você aprendeu, em ordem imprevisível.','Quando as perguntas vierem misturadas, seu cérebro vai aprender a reconhecer cada situação num piscar de olhos.',null,'[{"kind":"interleave","count":8}]'::jsonb),
  ('L001-08','L001',8,'A Visita Pontual','Viver uma visita completa e escolher a atitude certa em cada ponto de parada.','Quando chegar cada ponto de parada, você vai escolher como um verdadeiro anfitrião.',null,'[]'::jsonb),
  ('L001-09','L001',9,'Revisão cirúrgica','Reforçar o que está mais perto de ser esquecido e as palavras de pronúncia mais difícil.','Quando você revisar agora o que estava fraco, essas palavras vão ficar firmes por muito mais tempo.',null,'[{"kind":"review","count":8}]'::jsonb),
  ('L001-10','L001',10,'Checkpoint de Honra','Provar o domínio do nível: escuta, fala, gramática e tradução.','Quando você concluir este checkpoint, terá completado o primeiro nível do seu legado.',null,'[{"kind":"listen","ref":"c4"},{"kind":"context","q":"São 15h. Você encontra um senhor. O que você diz?","options":["Good afternoon, Sir.","Good night, Sir.","Good morning, Ma''am."],"answer":"Good afternoon, Sir.","speak":"Good afternoon, Sir.","explain":"À tarde, “Good afternoon”; para um homem, “Sir”."},{"kind":"fill","ref":"s12","blank":"are","options":["are","am","is"],"explain":"Com “you”, use “are”."},{"kind":"dictation","ref":"s9"},{"kind":"bank","ref":"s3","dir":"pt-en"},{"kind":"write","ref":"s7","hint":"none"},{"kind":"speak","ref":"s6"},{"kind":"roleplay"}]'::jsonb),
  ('L002-01','L002',1,'Vocabulário: Good morning, Sir','Conhecer os novos blocos de expressão do nível, com áudio normal e devagar.','Quando você concluir estes 3 minutos, estes novos blocos de expressão já vão soar familiares.',null,'[{"kind":"learn","ref":"c1"},{"kind":"learn","ref":"c2"},{"kind":"learn","ref":"c3"},{"kind":"learn","ref":"c4"},{"kind":"learn","ref":"c5"},{"kind":"learn","ref":"c6"},{"kind":"choose","ref":"c1","dir":"en-pt"},{"kind":"listen","ref":"c2"},{"kind":"choose","ref":"c3","dir":"pt-en"},{"kind":"choose","ref":"c4","dir":"en-pt"}]'::jsonb),
