insert into level_chunks (id,level_id,ref,en,pt,note) values
  ('L001:c1','L001','c1','Good morning','Bom dia','Use até o meio-dia.'),
  ('L001:c2','L001','c2','Good afternoon','Boa tarde','Do meio-dia até o fim da tarde.'),
  ('L001:c3','L001','c3','Good evening','Boa noite (ao chegar)','Para cumprimentar quem você encontra à noite.'),
  ('L001:c4','L001','c4','Good night','Boa noite (ao se despedir)','Só na despedida ou antes de dormir. Nunca para cumprimentar.'),
  ('L001:c5','L001','c5','Hello','Olá','Serve para qualquer hora do dia.'),
  ('L001:c6','L001','c6','Goodbye','Até logo / Adeus','Despedida educada.'),
  ('L001:c7','L001','c7','Sir','Senhor','Tratamento respeitoso para um homem. Use sem o nome: “Good morning, Sir.”'),
  ('L001:c8','L001','c8','Ma''am','Senhora','Tratamento respeitoso para uma mulher. Pronuncia-se “mém”.'),
  ('L001:c9','L001','c9','How are you?','Como vai?','Pergunta de cortesia ao cumprimentar.'),
  ('L001:c10','L001','c10','I am fine','Estou bem',null),
  ('L001:c11','L001','c11','Thank you','Obrigado / Obrigada','Em inglês é igual para homens e mulheres.'),
  ('L001:c12','L001','c12','You are on time','Você chegou na hora','Elogio à pontualidade.'),
