insert into level_sentences (id,level_id,ref,character_id,en,pt,alt) values
  ('L001:s1','L001','s1','ayrton','Good morning, Ma''am.','Bom dia, senhora.',null),
  ('L001:s2','L001','s2','alice','Good morning, Sir. How are you?','Bom dia, senhor. Como vai?',null),
  ('L001:s3','L001','s3','ayrton','I am fine, thank you. And you?','Estou bem, obrigado. E a senhora?','["I am fine, thanks. And you?","I am well, thank you. And you?"]'::jsonb),
  ('L001:s4','L001','s4','alice','I am fine, thank you.','Estou bem, obrigada.','["I am fine, thanks.","I am well, thank you."]'::jsonb),
  ('L001:s5','L001','s5','helena','Good afternoon, Sir. You are on time.','Boa tarde, senhor. O senhor chegou na hora.',null),
  ('L001:s6','L001','s6','lucas','Thank you, Ma''am. Punctuality is respect.','Obrigado, senhora. Pontualidade é respeito.',null),
  ('L001:s7','L001','s7','lucas','Good evening, Sir.','Boa noite, senhor. (chegando)',null),
  ('L001:s8','L001','s8','helena','Good night, and thank you.','Boa noite, e obrigada. (despedindo-se)','["Good night and thank you."]'::jsonb),
  ('L001:s9','L001','s9','alice','Hello, I am Alice.','Olá, eu sou a Alice.','["Hi, I am Alice."]'::jsonb),
  ('L001:s10','L001','s10','lucas','We are on time.','Nós chegamos na hora.',null),
  ('L001:s11','L001','s11','ayrton','Goodbye, Sir.','Até logo, senhor.','["Bye, Sir."]'::jsonb),
  ('L001:s12','L001','s12','helena','You are on time.','Você chegou na hora.',null);
insert into level_dialogues (id,level_id,ref,title,vocab,lines) values
  ('L001:d1','L001','d1','O concerto de Helena','["c5","c6","c11"]'::jsonb,'[{"who":"lucas","en":"Good evening, Sir. Good evening, Ma''am.","pt":"Boa noite, senhor. Boa noite, senhora."},{"who":"ayrton","en":"Good evening, Lucas! Hello, Alice.","pt":"Boa noite, Lucas! Olá, Alice."},{"who":"helena","en":"You are on time! Thank you.","pt":"Vocês chegaram na hora! Obrigada."},{"who":"alice","en":"Punctuality is respect, Helena.","pt":"Pontualidade é respeito, Helena."},{"who":"lucas","en":"How are you, Ayrton?","pt":"Como vai, Ayrton?"},{"who":"ayrton","en":"I am fine, thank you. And you?","pt":"Estou bem, obrigado. E você?"}]'::jsonb),
  ('L002:d1','L002','d1','Good morning, Sir','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"alice","en":"Good morning, Sir.","pt":"Bom dia, senhor."},{"who":"ayrton","en":"Good morning, Ma''am. You are on time.","pt":"Bom dia, senhora. A senhora está pontual."},{"who":"alice","en":"Punctuality is a form of respect.","pt":"A pontualidade é uma forma de respeito."},{"who":"ayrton","en":"Indeed. Good afternoon, and goodbye.","pt":"De fato. Boa tarde e adeus."}]'::jsonb),
  ('L002:d2','L002','d2','Nice to meet you','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"ayrton","en":"My name is Ayrton. I am an engineer.","pt":"Meu nome é Ayrton. Sou engenheiro."},{"who":"alice","en":"Nice to meet you, Mister Ayrton. I am Alice.","pt":"Prazer em conhecê-lo, senhor Ayrton. Sou Alice."},{"who":"ayrton","en":"Welcome to our meeting, Doctor Alice.","pt":"Bem-vinda à nossa reunião, doutora Alice."},{"who":"alice","en":"Thank you. The pleasure is mine.","pt":"Obrigada. O prazer é meu."}]'::jsonb),
  ('L002:d3','L002','d3','I am, you are','["c13","c14","c15","c16","c17","c18"]'::jsonb,'[{"who":"alice","en":"I am a lawyer. You are an engineer.","pt":"Sou advogada. Você é engenheiro."},{"who":"ayrton","en":"Yes. He is a soldier, and she is a teacher.","pt":"Sim. Ele é soldado e ela é professora."},{"who":"alice","en":"We are neighbors and they are our friends.","pt":"Somos vizinhos e eles são nossos amigos."},{"who":"ayrton","en":"We are ready to begin.","pt":"Estamos prontos para começar."}]'::jsonb),
  ('L002:d4','L002','d4','Courtesy and manners','["c19","c20","c21","c22","c23","c24"]'::jsonb,'[{"who":"ayrton","en":"Excuse me, Ma''am. Please sit here.","pt":"Com licença, senhora. Por favor, sente-se aqui."},{"who":"alice","en":"Thank you very much, Sir.","pt":"Muito obrigada, senhor."},{"who":"ayrton","en":"You are welcome. I am sorry for the delay.","pt":"De nada. Sinto muito pelo atraso."},{"who":"alice","en":"No problem. I will help you with pleasure.","pt":"Sem problema. Eu o ajudarei com prazer."}]'::jsonb),
  ('L006:d1','L006','d1','My family','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"maria","en":"This is my husband, Gabriel.","pt":"Este é meu marido, Gabriel."},{"who":"gabriel","en":"And this is my wife, Maria.","pt":"E esta é minha esposa, Maria."},{"who":"davi","en":"I am your son, Davi. I love my mother and my father.","pt":"Sou seu filho, Davi. Amo minha mãe e meu pai."},{"who":"liz","en":"I am your daughter, Liz.","pt":"Sou sua filha, Liz."}]'::jsonb),
  ('L006:d2','L006','d2','Rooms of the house','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"maria","en":"Welcome to our home. This is the living room.","pt":"Bem-vindos ao nosso lar. Esta é a sala de estar."},{"who":"davi","en":"Mom, where is Dad?","pt":"Mãe, onde está o papai?"},{"who":"maria","en":"He is in the kitchen. He is cooking.","pt":"Ele está na cozinha. Está cozinhando."},{"who":"liz","en":"I am in the garden with the flowers.","pt":"Estou no jardim com as flores."}]'::jsonb),
  ('L006:d3','L006','d3','Family meals','["c13","c14","c15","c16","c17","c18"]'::jsonb,'[{"who":"gabriel","en":"Dinner is ready. Please come to the table.","pt":"O jantar está pronto. Venham à mesa, por favor."},{"who":"davi","en":"I want soup and bread, please.","pt":"Quero sopa e pão, por favor."},{"who":"liz","en":"I want water, Dad.","pt":"Quero água, papai."},{"who":"maria","en":"We eat dinner together every night.","pt":"Jantamos juntos toda noite."}]'::jsonb),
  ('L006:d4','L006','d4','Thanks at the table','["c19","c20","c21","c22","c23","c24"]'::jsonb,'[{"who":"gabriel","en":"Let us give thanks. Lord, bless this food.","pt":"Vamos dar graças. Senhor, abençoe este alimento."},{"who":"liz","en":"Amen.","pt":"Amém."},{"who":"davi","en":"Pass the bread, please. This soup is delicious.","pt":"Passe o pão, por favor. Esta sopa está deliciosa."},{"who":"maria","en":"Thank you, my dear. Would you like more?","pt":"Obrigada, querido. Você quer mais?"}]'::jsonb),
  ('L011:d1','L011','d1','Professions','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"jose","en":"I am the founder of this company.","pt":"Sou o fundador desta empresa."},{"who":"flavia","en":"I am the manager of a farm. My husband is an engineer.","pt":"Sou a gestora de uma fazenda. Meu marido é engenheiro."},{"who":"jose","en":"My wife is an architect. Work is a blessing.","pt":"Minha esposa é arquiteta. O trabalho é uma bênção."},{"who":"flavia","en":"Good work builds a good country.","pt":"O bom trabalho constrói um bom país."}]'::jsonb),
  ('L011:d2','L011','d2','Numbers and time','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"jose","en":"What time is it?","pt":"Que horas são?"},{"who":"flavia","en":"It is eight o''clock.","pt":"São oito horas em ponto."},{"who":"jose","en":"The meeting is at nine. We have one hour.","pt":"A reunião é às nove. Temos uma hora."},{"who":"flavia","en":"Ten people will come. We will be ready.","pt":"Dez pessoas virão. Estaremos prontos."}]'::jsonb),
  ('L011:d3','L011','d3','A productive routine','["c13","c14","c15","c16","c17","c18"]'::jsonb,'[{"who":"flavia","en":"I wake up early every day.","pt":"Eu acordo cedo todos os dias."},{"who":"jose","en":"I work hard, and I rest on Sunday.","pt":"Eu trabalho duro e descanso no domingo."},{"who":"flavia","en":"Never be late. Time is a gift.","pt":"Nunca se atrase. O tempo é um presente."},{"who":"jose","en":"A good routine is the road to success.","pt":"Uma boa rotina é o caminho para o sucesso."}]'::jsonb),
  ('L011:d4','L011','d4','Business basics','["c19","c20","c21","c22","c23","c24"]'::jsonb,'[{"who":"jose","en":"Honesty is the base of every good business.","pt":"A honestidade é a base de todo bom negócio."},{"who":"flavia","en":"We have an agreement. Please sign the contract.","pt":"Temos um acordo. Por favor, assine o contrato."},{"who":"jose","en":"Profit comes from hard work.","pt":"O lucro vem do trabalho duro."},{"who":"flavia","en":"And private property must be respected.","pt":"E a propriedade privada deve ser respeitada."}]'::jsonb),
  ('L016:d1','L016','d1','Directions','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"ayrton","en":"Excuse me, Captain. Where is the city hall?","pt":"Com licença, capitão. Onde fica a prefeitura?"},{"who":"lucas","en":"Go straight ahead. Turn left at the corner.","pt":"Siga em frente. Vire à esquerda na esquina."},{"who":"ayrton","en":"Is it far from here?","pt":"Fica longe daqui?"},{"who":"lucas","en":"No, it is near. It is on your right.","pt":"Não, é perto. Fica à sua direita."}]'::jsonb),
  ('L016:d2','L016','d2','Places in the city','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"lucas","en":"This is a peaceful city. The church is near the school.","pt":"Esta é uma cidade pacífica. A igreja fica perto da escola."},{"who":"ayrton","en":"I am building a new hospital next to the park.","pt":"Estou construindo um novo hospital ao lado do parque."},{"who":"lucas","en":"The bank and the courthouse are on the same street.","pt":"O banco e o fórum ficam na mesma rua."},{"who":"ayrton","en":"A good city needs order.","pt":"Uma boa cidade precisa de ordem."}]'::jsonb),
  ('L016:d3','L016','d3','Our country','["c13","c14","c15","c16","c17","c18"]'::jsonb,'[{"who":"lucas","en":"I am a soldier. I serve my country.","pt":"Sou soldado. Sirvo meu país."},{"who":"ayrton","en":"I am a citizen. I respect our flag.","pt":"Sou cidadão. Respeito nossa bandeira."},{"who":"lucas","en":"We stand for the anthem with respect.","pt":"Ficamos de pé com respeito durante o hino."},{"who":"ayrton","en":"We love our homeland.","pt":"Amamos nossa pátria."}]'::jsonb),
  ('L016:d4','L016','d4','Civic duty','["c19","c20","c21","c22","c23","c24"]'::jsonb,'[{"who":"lucas","en":"Duty comes before comfort.","pt":"O dever vem antes do conforto."},{"who":"ayrton","en":"We obey the law, and we vote with responsibility.","pt":"Obedecemos à lei e votamos com responsabilidade."},{"who":"lucas","en":"Order protects our freedom.","pt":"A ordem protege nossa liberdade."},{"who":"ayrton","en":"Free men serve their country with honor.","pt":"Homens livres servem seu país com honra."}]'::jsonb),
  ('L017:d1','L017','d1','Days of the week','["c1","c2","c3","c4","c5","c6","c7"]'::jsonb,'[{"who":"beto","en":"Children, what day is today?","pt":"Crianças, que dia é hoje?"},{"who":"gael","en":"Today is Sunday, Dad!","pt":"Hoje é domingo, papai!"},{"who":"beto","en":"Correct. Monday comes after Sunday, and Friday comes before Saturday.","pt":"Correto. A segunda vem depois do domingo, e a sexta vem antes do sábado."},{"who":"laura","en":"I like Sunday the most.","pt":"Eu gosto mais do domingo."}]'::jsonb),
  ('L017:d2','L017','d2','Sunday with the family','["c8","c9","c10","c11","c12","c13"]'::jsonb,'[{"who":"clara","en":"On Sunday, we go to church together.","pt":"No domingo, vamos juntos à igreja."},{"who":"gael","en":"We pray, and we read the Bible.","pt":"Nós oramos e lemos a Bíblia."},{"who":"beto","en":"Then we visit the grandparents. It is a family tradition.","pt":"Depois visitamos os avós. É uma tradição de família."},{"who":"laura","en":"Family is a blessing.","pt":"A família é uma bênção."}]'::jsonb),
  ('L017:d3','L017','d3','The cardinal virtues','["c14","c15","c16","c17","c18","c19"]'::jsonb,'[{"who":"beto","en":"A virtue is a good habit. There are four cardinal virtues.","pt":"Uma virtude é um bom hábito. Há quatro virtudes cardeais."},{"who":"clara","en":"They are prudence, justice, fortitude and temperance.","pt":"São prudência, justiça, fortaleza e temperança."},{"who":"gael","en":"Prudence means thinking before acting.","pt":"Prudência significa pensar antes de agir."},{"who":"beto","en":"And faith gives us strength.","pt":"E a fé nos dá força."}]'::jsonb),
  ('L017:d4','L017','d4','Proverbs and wisdom','["c20","c21","c22","c23","c24","c25"]'::jsonb,'[{"who":"beto","en":"A proverb is a short sentence full of wisdom.","pt":"Um provérbio é uma frase curta cheia de sabedoria."},{"who":"clara","en":"Honor your father and your mother.","pt":"Honra teu pai e tua mãe."},{"who":"gael","en":"A soft answer turns away anger.","pt":"A resposta branda desvia o furor."},{"who":"beto","en":"Be humble, be diligent and be patient.","pt":"Seja humilde, diligente e paciente."}]'::jsonb),
  ('L021:d1','L021','d1','Colors','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"miguel","en":"The flag is green and yellow, and it has a blue circle.","pt":"A bandeira é verde e amarela, e tem um círculo azul."},{"who":"heloisa","en":"My dress is white.","pt":"Meu vestido é branco."},{"who":"arthur","en":"My shoes are black. My ball is red.","pt":"Meus sapatos são pretos. Minha bola é vermelha."},{"who":"cecilia","en":"I like all the colors.","pt":"Eu gosto de todas as cores."}]'::jsonb),
  ('L021:d2','L021','d2','Animals','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"noah","en":"There is a horse and a cow on the farm.","pt":"Há um cavalo e uma vaca na fazenda."},{"who":"antonella","en":"I see a little bird.","pt":"Eu vejo um passarinho."},{"who":"theo","en":"Look! The eagle is flying high.","pt":"Olhem! A águia está voando alto."},{"who":"maite","en":"Doggy! My dog is nice.","pt":"Cachorrinho! Meu cachorro é legal."}]'::jsonb),
  ('L021:d3','L021','d3','Nature and outdoor play','["c13","c14","c15","c16","c17","c18"]'::jsonb,'[{"who":"davi","en":"The sun is bright. Let us play outside.","pt":"O sol está forte. Vamos brincar lá fora."},{"who":"liz","en":"I see a big tree near the river.","pt":"Eu vejo uma árvore grande perto do rio."},{"who":"miguel","en":"We can climb the mountain with Dad.","pt":"Podemos subir a montanha com o papai."},{"who":"heloisa","en":"Look at the rain. God makes the flowers grow.","pt":"Olhe a chuva. Deus faz as flores crescerem."}]'::jsonb),
  ('L021:d4','L021','d4','Obedience and school','["c19","c20","c21","c22","c23","c24"]'::jsonb,'[{"who":"arthur","en":"Dad says: obey your parents and listen to your teacher.","pt":"O papai diz: obedeça seus pais e ouça sua professora."},{"who":"noah","en":"Mom, may I play now?","pt":"Mamãe, posso brincar agora?"},{"who":"flavia","en":"First, finish your homework, Noah.","pt":"Primeiro, termine sua lição de casa, Noah."},{"who":"noah","en":"Yes, Mom. I will obey.","pt":"Sim, mamãe. Eu vou obedecer."}]'::jsonb),
  ('L027:d1','L027','d1','Yesterday I kept my word','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"gael","en":"Dad, yesterday I found a wallet at school.","pt":"Pai, ontem eu achei uma carteira na escola."},{"who":"beto","en":"What did you do with it?","pt":"O que você fez com ela?"},{"who":"gael","en":"I gave it to the teacher. It was not mine.","pt":"Eu a entreguei à professora. Não era minha."},{"who":"beto","en":"Honesty is the best path, my son. I am proud of you.","pt":"A honestidade é o melhor caminho, meu filho. Tenho orgulho de você."}]'::jsonb),
  ('L027:d2','L027','d2','Tomorrow we will save','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"gael","en":"Dad, I am going to save my money.","pt":"Pai, eu vou poupar o meu dinheiro."},{"who":"beto","en":"Good. What will you buy?","pt":"Bom. O que você vai comprar?"},{"who":"gael","en":"I will buy a gift for Mom. Saving is better than spending.","pt":"Vou comprar um presente para a mamãe. Poupar é melhor que gastar."},{"who":"beto","en":"Smart choice. Small savings will become a big reward.","pt":"Escolha inteligente. Pequenas economias se tornarão uma grande recompensa."}]'::jsonb),
  ('L053:d1','L053','d1','We have built this company','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"flavia","en":"We have built this company with honest work.","pt":"Nós construímos esta empresa com trabalho honesto."},{"who":"jose","en":"Yes. We have never broken a contract.","pt":"Sim. Nunca quebramos um contrato."},{"who":"flavia","en":"If we keep our word, customers will trust us.","pt":"Se cumprirmos a palavra, os clientes confiarão em nós."},{"who":"jose","en":"We must serve them well. That is true leadership.","pt":"Devemos servi-los bem. Isso é liderança de verdade."}]'::jsonb),
  ('L053:d2','L053','d2','Have you read the contract?','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"beatriz","en":"José, have you read the new contract?","pt":"José, você já leu o novo contrato?"},{"who":"jose","en":"Yes. I have read every line. We should sign it.","pt":"Sim. Li cada linha. Deveríamos assiná-lo."},{"who":"beatriz","en":"If the price is fair, both sides will win.","pt":"Se o preço for justo, os dois lados ganharão."},{"who":"jose","en":"Exactly. A good deal serves everyone.","pt":"Exatamente. Um bom negócio serve a todos."}]'::jsonb),
  ('L079:d1','L079','d1','Freedoms were protected','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"alice","en":"Our freedoms were protected by brave citizens.","pt":"Nossas liberdades foram protegidas por cidadãos corajosos."},{"who":"lucas","en":"And they must be defended by every generation.","pt":"E devem ser defendidas por cada geração."},{"who":"alice","en":"The law is obeyed here, and justice is served.","pt":"A lei é obedecida aqui, e a justiça é feita."},{"who":"lucas","en":"Order and liberty are not enemies. They are partners.","pt":"Ordem e liberdade não são inimigas. São parceiras."}]'::jsonb),
  ('L079:d2','L079','d2','The judge said','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"lucas","en":"The judge said the law would be respected.","pt":"A juíza disse que a lei seria respeitada."},{"who":"alice","en":"She told us that every citizen had the right to speak.","pt":"Ela nos disse que todo cidadão tinha o direito de falar."},{"who":"lucas","en":"If people had not defended their rights, they would have lost them.","pt":"Se as pessoas não tivessem defendido seus direitos, os teriam perdido."},{"who":"alice","en":"Freedom is protected by those who are willing to defend it.","pt":"A liberdade é protegida por aqueles que estão dispostos a defendê-la."}]'::jsonb),
  ('L112:d1','L112','d1','Rarely does a nation','["c1","c2","c3","c4","c5","c6"]'::jsonb,'[{"who":"ayrton","en":"Rarely does a nation produce such courage.","pt":"Raramente uma nação produz tanta coragem."},{"who":"alice","en":"Not only did they fight bravely, but they also governed wisely.","pt":"Eles não apenas lutaram com bravura, mas também governaram com sabedoria."},{"who":"ayrton","en":"Never have I read a speech so moving.","pt":"Nunca li um discurso tão comovente."},{"who":"alice","en":"Seldom is truth easy, yet it is always worth defending.","pt":"Raramente a verdade é fácil, mas ela sempre vale ser defendida."}]'::jsonb),
  ('L112:d2','L112','d2','Let us not rush','["c7","c8","c9","c10","c11","c12"]'::jsonb,'[{"who":"jose","en":"I propose that the meeting be held on Monday.","pt":"Proponho que a reunião seja realizada na segunda-feira."},{"who":"ayrton","en":"It is essential that every party be heard.","pt":"É essencial que cada parte seja ouvida."},{"who":"jose","en":"Let us not put the cart before the horse. First, the facts.","pt":"Não coloquemos a carroça na frente dos bois. Primeiro, os fatos."},{"who":"ayrton","en":"Wisely said. We will proceed with prudence.","pt":"Bem dito. Prosseguiremos com prudência."}]'::jsonb);
insert into listening_stations (level_id,title,lines,questions) values
  ('L001','Encontro na praça','[{"who":"helena","en":"Good afternoon, Alice. How are you?","pt":"Boa tarde, Alice. Como vai?"},{"who":"alice","en":"Hello, Helena. I am fine, thank you. And you?","pt":"Olá, Helena. Estou bem, obrigada. E você?"},{"who":"helena","en":"I am fine, thank you.","pt":"Estou bem, obrigada."},{"who":"lucas","en":"Good afternoon, Ma''am. Good afternoon, Alice.","pt":"Boa tarde, senhora. Boa tarde, Alice."},{"who":"helena","en":"Good afternoon, Sir. You are on time!","pt":"Boa tarde, senhor. O senhor chegou na hora!"},{"who":"lucas","en":"Thank you, Ma''am. Punctuality is respect.","pt":"Obrigado, senhora. Pontualidade é respeito."}]'::jsonb,'[{"q":"Em que período do dia acontece a conversa?","options":["De manhã","À tarde","À noite"],"answer":"À tarde","lang":"pt"},{"q":"Como Alice está?","options":["Bem","Cansada","Triste"],"answer":"Bem","lang":"pt"},{"q":"Quem chegou na hora certa?","options":["Lucas","Ayrton","Ninguém"],"answer":"Lucas","lang":"pt"}]'::jsonb),
  ('L002','A Reunião','[{"who":"ayrton","en":"Good morning, Doctor Alice. Welcome to our meeting.","pt":"Bom dia, doutora Alice. Bem-vinda à nossa reunião."},{"who":"alice","en":"Good morning, Mister Ayrton. Thank you, Sir.","pt":"Bom dia, senhor Ayrton. Obrigada, senhor."},{"who":"ayrton","en":"Our meeting starts at nine o''clock. You are on time.","pt":"Nossa reunião começa às nove horas. A senhora está pontual."},{"who":"alice","en":"Punctuality is respect, Sir. I always arrive early.","pt":"Pontualidade é respeito, senhor. Eu sempre chego cedo."},{"who":"ayrton","en":"Excellent. Please, sit down.","pt":"Excelente. Por favor, sente-se."},{"who":"alice","en":"Thank you. The pleasure is mine.","pt":"Obrigada. O prazer é meu."}]'::jsonb,'[{"q":"A que horas começa a reunião?","options":["At eight","At nine","At ten"],"answer":"At nine","lang":"en"},{"q":"Como Alice descreve a pontualidade?","options":["As respect","As luck","As luxury"],"answer":"As respect","lang":"en"},{"q":"Quando Alice costuma chegar?","options":["Early","Late","Never"],"answer":"Early","lang":"en"}]'::jsonb),
  ('L006','O Jantar','[{"who":"maria","en":"Welcome to our home, neighbors. Dinner is ready.","pt":"Bem-vindos à nossa casa, vizinhos. O jantar está pronto."},{"who":"gabriel","en":"Please sit at the table. We have soup and fresh bread.","pt":"Por favor, sentem-se à mesa. Temos sopa e pão fresco."},{"who":"davi","en":"Mom, I set the table. I put five plates.","pt":"Mãe, eu arrumei a mesa. Coloquei cinco pratos."},{"who":"maria","en":"Thank you, Davi. Liz, please bring the water.","pt":"Obrigada, Davi. Liz, por favor, traga a água."},{"who":"liz","en":"Yes, Mom. Here is the water.","pt":"Sim, mãe. Aqui está a água."},{"who":"gabriel","en":"Let us give thanks before we eat.","pt":"Vamos agradecer antes de comer."}]'::jsonb,'[{"q":"O que há para o jantar?","options":["Soup and bread","Pizza and juice","Fish and rice"],"answer":"Soup and bread","lang":"en"},{"q":"Quantos pratos Davi colocou?","options":["Four","Five","Six"],"answer":"Five","lang":"en"},{"q":"O que fazem antes de comer?","options":["Give thanks","Watch TV","Wash the car"],"answer":"Give thanks","lang":"en"}]'::jsonb),
  ('L011','A Fábrica','[{"who":"jose","en":"Flavia, we open at seven o''clock every day.","pt":"Flavia, abrimos às sete horas todos os dias."},{"who":"flavia","en":"I know. My team arrives at six thirty.","pt":"Eu sei. Minha equipe chega às seis e meia."},{"who":"jose","en":"Good. Hard work builds a good company.","pt":"Bom. Trabalho duro constrói uma boa empresa."},{"who":"flavia","en":"We have twelve workers and three trucks.","pt":"Temos doze funcionários e três caminhões."},{"who":"jose","en":"Honest work deserves a fair salary.","pt":"Trabalho honesto merece um salário justo."},{"who":"flavia","en":"I agree. Payday is on Friday.","pt":"Concordo. O pagamento é na sexta-feira."}]'::jsonb,'[{"q":"A que horas a fábrica abre?","options":["At seven","At six","At nine"],"answer":"At seven","lang":"en"},{"q":"Quantos funcionários há?","options":["Ten","Twelve","Three"],"answer":"Twelve","lang":"en"},{"q":"Qual é o dia do pagamento?","options":["Monday","Friday","Sunday"],"answer":"Friday","lang":"en"}]'::jsonb),
  ('L016','A Praça','[{"who":"lucas","en":"Excuse me, Sir. Where is the city hall?","pt":"Com licença, senhor. Onde fica a prefeitura?"},{"who":"ayrton","en":"Go straight and turn left at the flag.","pt":"Siga em frente e vire à esquerda na bandeira."},{"who":"lucas","en":"Thank you. Is the library near?","pt":"Obrigado. A biblioteca é perto?"},{"who":"ayrton","en":"Yes, it is next to the church.","pt":"Sim, fica ao lado da igreja."},{"who":"lucas","en":"I serve my country, and I respect the law.","pt":"Eu sirvo ao meu país e respeito a lei."},{"who":"ayrton","en":"That is an honorable duty, Sir.","pt":"Esse é um dever honroso, senhor."}]'::jsonb,'[{"q":"Onde virar à esquerda?","options":["At the flag","At the bank","At the school"],"answer":"At the flag","lang":"en"},{"q":"Onde fica a biblioteca?","options":["Next to the church","Behind the bank","Near the river"],"answer":"Next to the church","lang":"en"},{"q":"O que Lucas faz?","options":["He serves his country","He sells cars","He teaches piano"],"answer":"He serves his country","lang":"en"}]'::jsonb),
  ('L017','O Domingo','[{"who":"beto","en":"Today is Sunday. We go to church as a family.","pt":"Hoje é domingo. Vamos à igreja em família."},{"who":"clara","en":"Gael, put on your good shoes.","pt":"Gael, calce os seus sapatos bons."},{"who":"gael","en":"Yes, Mom. Dad, will you tell a story after lunch?","pt":"Sim, mãe. Pai, você vai contar uma história depois do almoço?"},{"who":"beto","en":"Yes. A story about an honest king.","pt":"Sim. Uma história sobre um rei honesto."},{"who":"laura","en":"I like stories, Daddy.","pt":"Eu gosto de histórias, papai."},{"who":"clara","en":"After the story, we will thank God for our family.","pt":"Depois da história, agradeceremos a Deus pela nossa família."}]'::jsonb,'[{"q":"Que dia é hoje?","options":["Sunday","Monday","Friday"],"answer":"Sunday","lang":"en"},{"q":"Sobre o que será a história?","options":["An honest king","A funny dog","A long trip"],"answer":"An honest king","lang":"en"},{"q":"O que farão depois da história?","options":["Thank God","Play soccer","Go shopping"],"answer":"Thank God","lang":"en"}]'::jsonb),
  ('L021','A Brincadeira','[{"who":"theo","en":"Miguel, the dog is brown and the cat is white.","pt":"Miguel, o cachorro é marrom e o gato é branco."},{"who":"miguel","en":"Yes. We must be kind to animals.","pt":"Sim. Devemos ser gentis com os animais."},{"who":"cecilia","en":"Look at the green trees! Nature is beautiful.","pt":"Olhem as árvores verdes! A natureza é linda."},{"who":"noah","en":"Mom said we should obey and come home at six.","pt":"A mamãe disse que devemos obedecer e voltar para casa às seis."},{"who":"antonella","en":"Okay, Noah. I obey Mom and Dad.","pt":"Está bem, Noah. Eu obedeço à mamãe e ao papai."},{"who":"arthur","en":"Obedience makes a family happy.","pt":"A obediência faz uma família feliz."}]'::jsonb,'[{"q":"Qual é a cor do cachorro?","options":["Brown","White","Green"],"answer":"Brown","lang":"en"},{"q":"A que horas devem voltar?","options":["At six","At nine","At noon"],"answer":"At six","lang":"en"},{"q":"O que faz uma família feliz?","options":["Obedience","Money","Television"],"answer":"Obedience","lang":"en"}]'::jsonb),
  ('L027','Ontem em Família','[{"who":"beto","en":"Yesterday, Gael returned a lost wallet.","pt":"Ontem, o Gael devolveu uma carteira perdida."},{"who":"clara","en":"Honest boy! I am proud of him.","pt":"Menino honesto! Tenho orgulho dele."},{"who":"gael","en":"It was not mine, Mom. I gave it to the teacher.","pt":"Não era minha, mãe. Eu a entreguei à professora."},{"who":"laura","en":"Daddy, I saved two coins last week!","pt":"Papai, eu guardei duas moedas na semana passada!"},{"who":"beto","en":"Good girl. Small savings will become a big reward.","pt":"Muito bem, filha. Pequenas economias se tornarão uma grande recompensa."},{"who":"clara","en":"Last Sunday was a happy day for our family.","pt":"O último domingo foi um dia feliz para a nossa família."}]'::jsonb,'[{"q":"O que Gael devolveu?","options":["A wallet","A book","A watch"],"answer":"A wallet","lang":"en"},{"q":"Quantas moedas Laura guardou?","options":["Two coins","Ten coins","No coins"],"answer":"Two coins","lang":"en"},{"q":"Como foi o último domingo?","options":["A happy day","A sad day","A long day"],"answer":"A happy day","lang":"en"}]'::jsonb),
  ('L053','Contrato e Liderança','[{"who":"flavia","en":"We have signed the contract with our new customer.","pt":"Assinamos o contrato com o nosso novo cliente."},{"who":"jose","en":"Excellent. If we deliver on time, they will order again.","pt":"Excelente. Se entregarmos no prazo, eles pedirão de novo."},{"who":"beatriz","en":"Have you checked the delivery schedule?","pt":"Você conferiu o cronograma de entrega?"},{"who":"flavia","en":"Yes. I have checked it twice.","pt":"Sim. Conferi duas vezes."},{"who":"jose","en":"Good. A leader should serve the team first.","pt":"Bom. Um líder deve servir à equipe primeiro."},{"who":"beatriz","en":"And honest profit rewards honest work.","pt":"E o lucro honesto recompensa o trabalho honesto."}]'::jsonb,'[{"q":"Com quem assinaram o contrato?","options":["A new customer","A bank","A school"],"answer":"A new customer","lang":"en"},{"q":"Quantas vezes Flávia conferiu o cronograma?","options":["Twice","Once","Never"],"answer":"Twice","lang":"en"},{"q":"Segundo José, o que um líder deve fazer primeiro?","options":["Serve the team","Count the money","Go home"],"answer":"Serve the team","lang":"en"}]'::jsonb),
  ('L079','Liberdade e Justiça','[{"who":"alice","en":"Our liberties were won by courageous citizens.","pt":"Nossas liberdades foram conquistadas por cidadãos corajosos."},{"who":"lucas","en":"And they must be defended by every generation.","pt":"E devem ser defendidas por cada geração."},{"who":"alice","en":"The judge said the trial would begin on Monday.","pt":"A juíza disse que o julgamento começaria na segunda-feira."},{"who":"lucas","en":"I told her that I would be there as a witness.","pt":"Eu disse a ela que estaria lá como testemunha."},{"who":"alice","en":"If we had stayed silent, justice would have been delayed.","pt":"Se tivéssemos ficado em silêncio, a justiça teria sido adiada."},{"who":"lucas","en":"Truth must be spoken, even when it costs us.","pt":"A verdade precisa ser dita, mesmo quando nos custa."}]'::jsonb,'[{"q":"Quem conquistou as liberdades?","options":["Courageous citizens","Foreign kings","Nobody"],"answer":"Courageous citizens","lang":"en"},{"q":"Quando começa o julgamento?","options":["On Monday","On Friday","On Sunday"],"answer":"On Monday","lang":"en"},{"q":"Como Lucas estará no julgamento?","options":["As a witness","As a judge","As a lawyer"],"answer":"As a witness","lang":"en"}]'::jsonb),
  ('L112','Oratória','[{"who":"ayrton","en":"Rarely does a nation produce such courage.","pt":"Raramente uma nação produz tanta coragem."},{"who":"alice","en":"Not only did they fight bravely, but they also governed wisely.","pt":"Eles não apenas lutaram com bravura, mas também governaram com sabedoria."},{"who":"jose","en":"I propose that the next meeting be held on Monday.","pt":"Proponho que a próxima reunião seja realizada na segunda-feira."},{"who":"ayrton","en":"It is essential that every party be heard.","pt":"É essencial que cada parte seja ouvida."},{"who":"jose","en":"Let us not put the cart before the horse.","pt":"Não coloquemos a carroça na frente dos bois."},{"who":"alice","en":"Wisely said. First the facts, then the decision.","pt":"Bem dito. Primeiro os fatos, depois a decisão."}]'::jsonb,'[{"q":"Quando será a próxima reunião?","options":["On Monday","On Friday","On Sunday"],"answer":"On Monday","lang":"en"},{"q":"O que é essencial, segundo Ayrton?","options":["Every party be heard","Everyone agree","Nobody speak"],"answer":"Every party be heard","lang":"en"},{"q":"Qual expressão José usa?","options":["Put the cart before the horse","Break the ice","Hit the road"],"answer":"Put the cart before the horse","lang":"en"}]'::jsonb);
insert into chronicles (level_id,title,icon,intro) values
  ('L001','A Visita Pontual','🕰️','Os novos vizinhos, Alice e Lucas, visitam Ayrton e Helena. Cumprimente com respeito em cada momento da visita.'),
  ('L002','O Relógio de Bolso de Ayrton','⌚','Ayrton ensina ao filho Miguel o valor da pontualidade e da palavra empenhada.'),
  ('L006','O Jantar de Domingo na Casa de Maria Fulana','🍲','Maria Fulana e Gabriel preparam uma recepção calorosa para os vizinhos.'),
  ('L011','O Primeiro Contrato de José','📜','José explica a Arthur e Cecília como funciona a criação de valor, o lucro honesto e o cumprimento de acordos.'),
  ('L016','A Lição de História do Professor Beto','🏛️','Beto leva Gael e Laura a um museu e narra o heroísmo de quem defendeu a pátria.'),
  ('L017','Situação Real: Tradição, Fé e Sabedoria','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.'),
  ('L021','Situação Real: Cores, Animais e Natureza','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.'),
  ('L027','Situação Real: Ontem e Amanhã em Família','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.'),
  ('L053','Situação Real: Livre Iniciativa e Contratos','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.'),
  ('L079','Situação Real: Liberdades Individuais','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.'),
  ('L112','Situação Real: Oratória: Inversões e Subjuntivo','🎭','Acompanhe cada cena e escolha a fala certa em cada ponto de parada.');
