insert into chronicle_segments (id,level_id,position,lines,stop_kind,stop_question,stop_options,stop_answer,stop_why,stop_lang) values
  ('L001:1','L001',1,'[{"who":"helena","en":"Ayrton, the neighbors are here!","pt":"Ayrton, os vizinhos chegaram!"},{"who":"ayrton","en":"It is six o''clock. They are on time.","pt":"São seis horas. Eles chegaram na hora."}]'::jsonb,'deduce','São seis da tarde e os vizinhos estão chegando. Qual cumprimento Ayrton deve usar?','["Good evening","Good morning","Good night"]'::jsonb,'Good evening','Ao chegar, à noitinha, use “Good evening”. “Good night” é só para a despedida.','en'),
  ('L001:2','L001',2,'[{"who":"ayrton","en":"Good evening, Ma''am. Good evening, Sir.","pt":"Boa noite, senhora. Boa noite, senhor."},{"who":"lucas","en":"Good evening, Sir. I am Lucas, and this is Alice.","pt":"Boa noite, senhor. Eu sou Lucas, e esta é Alice."}]'::jsonb,'moral','Lucas apresentou a esposa. Qual é a resposta mais educada de Helena?','["Hello, Ma''am. Welcome!","What do you want?","Goodbye."]'::jsonb,'Hello, Ma''am. Welcome!','Receber com cortesia e um sorriso é o primeiro passo da hospitalidade.','en'),
  ('L001:3','L001',3,'[{"who":"helena","en":"How are you, Alice?","pt":"Como vai, Alice?"},{"who":"alice","en":"I am fine, thank you. And you?","pt":"Estou bem, obrigada. E você?"}]'::jsonb,'complete','Complete a resposta de Helena: “I ___ fine, thank you.”','["am","are","is"]'::jsonb,'am','Com “I”, o verbo to be é “am”: I am.','en'),
  ('L001:4','L001',4,'[{"who":"lucas","en":"It is late. Good night, Sir. Good night, Ma''am.","pt":"Está tarde. Boa noite, senhor. Boa noite, senhora."},{"who":"ayrton","en":"Good night, Lucas. Thank you for your visit.","pt":"Boa noite, Lucas. Obrigado pela visita."}]'::jsonb,'deduce','Por que agora Lucas diz “Good night”, e não “Good evening”?','["Porque está se despedindo","Porque é de manhã","Porque está chegando"]'::jsonb,'Porque está se despedindo','“Good night” é usado na despedida ou antes de dormir; “Good evening”, ao chegar.','pt'),
  ('L002:1','L002',1,'[{"who":"ayrton","en":"Miguel, look at my pocket watch. It was my father''s.","pt":"Miguel, olhe o meu relógio de bolso. Era do meu pai."},{"who":"miguel","en":"It is beautiful, Dad. Why do you carry it?","pt":"É lindo, pai. Por que o senhor o leva consigo?"},{"who":"ayrton","en":"Because time is a gift. We must not waste it.","pt":"Porque o tempo é um presente. Não devemos desperdiçá-lo."}]'::jsonb,'deduce','O que Ayrton quer ensinar com o relógio?','["Time is a gift","Gold is everything","Watches are old"]'::jsonb,'Time is a gift','O relógio lembra que o tempo é um dom a ser bem usado.','en'),
  ('L002:2','L002',2,'[{"who":"ayrton","en":"We have a visit at three o''clock. It is an important visit.","pt":"Temos uma visita às três horas. É uma visita importante."},{"who":"miguel","en":"But Dad, my friends want me to play now.","pt":"Mas, pai, meus amigos querem que eu brinque agora."},{"who":"ayrton","en":"I gave my word to Mister Silva. A man keeps his word.","pt":"Dei a minha palavra ao senhor Silva. Um homem cumpre a sua palavra."}]'::jsonb,'moral','O que Miguel deve fazer?','["Go with Dad and keep the promise","Stay and play with friends","Tell a lie to avoid the visit"]'::jsonb,'Go with Dad and keep the promise','Cumprir a palavra empenhada vale mais do que a diversão do momento.','en'),
  ('L002:3','L002',3,'[{"who":"ayrton","en":"It is two thirty. We must leave now.","pt":"São duas e meia. Precisamos sair agora."},{"who":"miguel","en":"Dad, the car is not starting!","pt":"Pai, o carro não está pegando!"},{"who":"ayrton","en":"Stay calm. We will walk fast, and I will call Mister Silva.","pt":"Calma. Vamos andar depressa, e eu ligarei para o senhor Silva."}]'::jsonb,'deduce','O que Ayrton fará para honrar o compromisso?','["Walk fast and warn Mister Silva","Cancel the visit","Wait for the car all day"]'::jsonb,'Walk fast and warn Mister Silva','Quem leva o compromisso a sério busca uma solução e avisa a outra parte.','en'),
  ('L002:4','L002',4,'[{"who":"ayrton","en":"Mister Silva, we are here. Thank you for waiting.","pt":"Senhor Silva, chegamos. Obrigado por esperar."},{"who":"miguel","en":"Dad, now I understand. Punctuality is respect.","pt":"Pai, agora eu entendo. Pontualidade é respeito."}]'::jsonb,'complete','Complete a fala de Miguel: “Punctuality is ____.”','["respect","luck","hurry"]'::jsonb,'respect','Pontualidade é uma forma de respeito pelo tempo dos outros.','en'),
  ('L006:1','L006',1,'[{"who":"maria","en":"Gabriel, the neighbors will arrive at six. Is the roast ready?","pt":"Gabriel, os vizinhos chegam às seis. O assado está pronto?"},{"who":"gabriel","en":"Almost. Davi, please set the table.","pt":"Quase. Davi, por favor, arrume a mesa."},{"who":"davi","en":"Yes, Dad. How many plates do we need?","pt":"Sim, pai. Quantos pratos precisamos?"},{"who":"maria","en":"Four for us and two for our guests.","pt":"Quatro para nós e dois para os nossos convidados."}]'::jsonb,'complete','Complete: “We need six plates: four for us and ____ for our guests.”','["two","ten","one"]'::jsonb,'two','Quatro da família mais dois convidados somam seis pratos.','en'),
  ('L006:2','L006',2,'[{"who":"maria","en":"Welcome, neighbors! Please come in.","pt":"Bem-vindos, vizinhos! Entrem, por favor."},{"who":"davi","en":"Mom, Mrs. Santos looks tired.","pt":"Mãe, a dona Santos parece cansada."},{"who":"gabriel","en":"Make yourselves at home. Dinner is ready.","pt":"Fiquem à vontade. O jantar está pronto."}]'::jsonb,'moral','Qual é a melhor atitude de Maria?','["Offer her a chair and a glass of water","Ignore it and keep cooking","Ask her to leave early"]'::jsonb,'Offer her a chair and a glass of water','Hospitalidade é perceber a necessidade do hóspede e servi-lo.','en'),
  ('L006:3','L006',3,'[{"who":"gabriel","en":"Let us give thanks for this food and for good neighbors.","pt":"Vamos agradecer por esta comida e por bons vizinhos."},{"who":"liz","en":"Can I say the prayer, Dad?","pt":"Posso fazer a oração, pai?"},{"who":"gabriel","en":"Of course, Liz.","pt":"Claro, Liz."}]'::jsonb,'deduce','O que acontece a seguir?','["Liz says a short prayer of thanks","Everyone starts eating at once","Liz leaves the table"]'::jsonb,'Liz says a short prayer of thanks','Gabriel acabou de permitir; a oração de gratidão vem antes da refeição.','en'),
  ('L006:4','L006',4,'[{"who":"davi","en":"Mom, may I have more soup, please?","pt":"Mãe, posso tomar mais sopa, por favor?"},{"who":"maria","en":"Yes, Davi. Good manners make a meal sweeter.","pt":"Sim, Davi. Boas maneiras tornam a refeição mais doce."}]'::jsonb,'complete','Complete: “May I have more soup, ____?”','["please","now","fast"]'::jsonb,'please','“Please” é a palavra de cortesia ao pedir algo.','en'),
  ('L011:1','L011',1,'[{"who":"jose","en":"Arthur, Cecília, today I will sign a contract.","pt":"Arthur, Cecília, hoje vou assinar um contrato."},{"who":"arthur","en":"What is a contract, Dad?","pt":"O que é um contrato, pai?"},{"who":"jose","en":"It is a promise written on paper.","pt":"É uma promessa escrita no papel."}]'::jsonb,'deduce','O que é um contrato para José?','["A promise written on paper","A game","A gift"]'::jsonb,'A promise written on paper','Um contrato registra uma palavra dada que deve ser cumprida.','en'),
  ('L011:2','L011',2,'[{"who":"cecilia","en":"Dad, will you earn money?","pt":"Pai, o senhor vai ganhar dinheiro?"},{"who":"jose","en":"Yes, honest profit. We create value, and customers pay for it.","pt":"Sim, lucro honesto. Criamos valor, e os clientes pagam por ele."},{"who":"arthur","en":"Is profit bad, Dad?","pt":"Lucro é ruim, pai?"}]'::jsonb,'moral','Como José responde?','["No. Honest profit rewards good work","Yes. Profit is always wrong","Profit is only luck"]'::jsonb,'No. Honest profit rewards good work','O lucro honesto é o prêmio de quem serve bem e cria valor.','en'),
  ('L011:3','L011',3,'[{"who":"jose","en":"The customer wants a lower price, but my cost is higher.","pt":"O cliente quer um preço menor, mas o meu custo é maior."},{"who":"arthur","en":"Can we change the contract and cheat him?","pt":"Podemos mudar o contrato e enganá-lo?"}]'::jsonb,'moral','O que José diz?','["No. A deal is a deal, and we keep our word","Yes, if he does not notice","Yes, if we need money"]'::jsonb,'No. A deal is a deal, and we keep our word','Honestidade não depende de ser descoberto: acordo é acordo.','en'),
  ('L011:4','L011',4,'[{"who":"jose","en":"We delivered on time. The customer paid and thanked us.","pt":"Entregamos no prazo. O cliente pagou e nos agradeceu."},{"who":"cecilia","en":"Dad, I want to build a business too!","pt":"Pai, eu também quero construir um negócio!"}]'::jsonb,'complete','Complete: “Hard work ____ off.”','["pays","stops","falls"]'::jsonb,'pays','“Hard work pays off” significa que o trabalho duro compensa.','en'),
  ('L016:1','L016',1,'[{"who":"beto","en":"Gael, Laura, welcome to the museum. Look at this old flag.","pt":"Gael, Laura, bem-vindos ao museu. Olhem esta bandeira antiga."},{"who":"gael","en":"Dad, who carried this flag?","pt":"Pai, quem carregou esta bandeira?"},{"who":"beto","en":"A brave soldier. He defended his country.","pt":"Um soldado corajoso. Ele defendeu o seu país."}]'::jsonb,'deduce','O que Beto vai contar?','["A story of a soldier who defended his country","A story about a cartoon","A story about shopping"]'::jsonb,'A story of a soldier who defended his country','Beto já disse que o soldado defendeu o país: é essa a história.','en'),
  ('L016:2','L016',2,'[{"who":"beto","en":"The soldier was hurt, but he did not leave his post.","pt":"O soldado estava ferido, mas não abandonou o seu posto."},{"who":"laura","en":"Daddy, was he afraid?","pt":"Papai, ele teve medo?"},{"who":"beto","en":"Yes, but courage is acting rightly even when we are afraid.","pt":"Sim, mas coragem é agir corretamente mesmo quando temos medo."}]'::jsonb,'moral','O que é coragem, segundo Beto?','["Acting rightly even when afraid","Never feeling fear","Showing off to others"]'::jsonb,'Acting rightly even when afraid','Coragem não é ausência de medo, é fazer o certo apesar dele.','en'),
  ('L016:3','L016',3,'[{"who":"gael","en":"What did the soldier do after the war?","pt":"O que o soldado fez depois da guerra?"},{"who":"beto","en":"He went home, worked hard, and raised his family.","pt":"Voltou para casa, trabalhou duro e criou a sua família."}]'::jsonb,'deduce','Como foi a vida do soldado depois da guerra?','["He returned home and worked honestly","He became rich by deceit","He left his family"]'::jsonb,'He returned home and worked honestly','O herói também é o homem que volta e sustenta a família com trabalho honesto.','en'),
  ('L016:4','L016',4,'[{"who":"laura","en":"I want to be brave like him.","pt":"Eu quero ser corajosa como ele."},{"who":"beto","en":"Brave and kind, my little one. History teaches us who we are.","pt":"Corajosa e bondosa, minha pequena. A história nos ensina quem somos."}]'::jsonb,'complete','Complete: “History teaches us who we ____.”','["are","is","was"]'::jsonb,'are','“Who we are”: o verbo concorda com “we”.','en'),
  ('L017:1','L017',1,'[{"who":"beto","en":"Children, what day is today?","pt":"Crianças, que dia é hoje?"},{"who":"gael","en":"Today is Sunday, Dad!","pt":"Hoje é domingo, papai!"},{"who":"beto","en":"Correct. Monday comes after Sunday, and Friday comes before Saturday.","pt":"Correto. A segunda vem depois do domingo, e a sexta vem antes do sábado."}]'::jsonb,'deduce','Qual é a próxima fala de Laura?','["I like Sunday the most.","Family is a blessing.","And faith gives us strength."]'::jsonb,'I like Sunday the most.','Laura diz: “I like Sunday the most.” — Eu gosto mais do domingo.','en'),
  ('L017:2','L017',2,'[{"who":"clara","en":"On Sunday, we go to church together.","pt":"No domingo, vamos juntos à igreja."},{"who":"gael","en":"We pray, and we read the Bible.","pt":"Nós oramos e lemos a Bíblia."},{"who":"beto","en":"Then we visit the grandparents. It is a family tradition.","pt":"Depois visitamos os avós. É uma tradição de família."}]'::jsonb,'deduce','Qual é a próxima fala de Laura?','["I like Sunday the most.","And faith gives us strength.","Family is a blessing."]'::jsonb,'Family is a blessing.','Laura diz: “Family is a blessing.” — A família é uma bênção.','en'),
  ('L017:3','L017',3,'[{"who":"beto","en":"A virtue is a good habit. There are four cardinal virtues.","pt":"Uma virtude é um bom hábito. Há quatro virtudes cardeais."},{"who":"clara","en":"They are prudence, justice, fortitude and temperance.","pt":"São prudência, justiça, fortaleza e temperança."},{"who":"gael","en":"Prudence means thinking before acting.","pt":"Prudência significa pensar antes de agir."}]'::jsonb,'deduce','Qual é a próxima fala de Beto?','["Family is a blessing.","And faith gives us strength.","I like Sunday the most."]'::jsonb,'And faith gives us strength.','Beto diz: “And faith gives us strength.” — E a fé nos dá força.','en'),
  ('L017:4','L017',4,'[{"who":"beto","en":"A proverb is a short sentence full of wisdom.","pt":"Um provérbio é uma frase curta cheia de sabedoria."},{"who":"clara","en":"Honor your father and your mother.","pt":"Honra teu pai e tua mãe."},{"who":"gael","en":"A soft answer turns away anger.","pt":"A resposta branda desvia o furor."}]'::jsonb,'deduce','Qual é a próxima fala de Beto?','["Be humble, be diligent and be patient.","I like Sunday the most.","Family is a blessing."]'::jsonb,'Be humble, be diligent and be patient.','Beto diz: “Be humble, be diligent and be patient.” — Seja humilde, diligente e paciente.','en'),
  ('L021:1','L021',1,'[{"who":"miguel","en":"The flag is green and yellow, and it has a blue circle.","pt":"A bandeira é verde e amarela, e tem um círculo azul."},{"who":"heloisa","en":"My dress is white.","pt":"Meu vestido é branco."},{"who":"arthur","en":"My shoes are black. My ball is red.","pt":"Meus sapatos são pretos. Minha bola é vermelha."}]'::jsonb,'deduce','Qual é a próxima fala de Cecília?','["I like all the colors.","Doggy! My dog is nice.","Look at the rain. God makes the flowers grow."]'::jsonb,'I like all the colors.','Cecília diz: “I like all the colors.” — Eu gosto de todas as cores.','en'),
  ('L021:2','L021',2,'[{"who":"noah","en":"There is a horse and a cow on the farm.","pt":"Há um cavalo e uma vaca na fazenda."},{"who":"antonella","en":"I see a little bird.","pt":"Eu vejo um passarinho."},{"who":"theo","en":"Look! The eagle is flying high.","pt":"Olhem! A águia está voando alto."}]'::jsonb,'deduce','Qual é a próxima fala de Maitê?','["I like all the colors.","Look at the rain. God makes the flowers grow.","Doggy! My dog is nice."]'::jsonb,'Doggy! My dog is nice.','Maitê diz: “Doggy! My dog is nice.” — Cachorrinho! Meu cachorro é legal.','en'),
  ('L021:3','L021',3,'[{"who":"davi","en":"The sun is bright. Let us play outside.","pt":"O sol está forte. Vamos brincar lá fora."},{"who":"liz","en":"I see a big tree near the river.","pt":"Eu vejo uma árvore grande perto do rio."},{"who":"miguel","en":"We can climb the mountain with Dad.","pt":"Podemos subir a montanha com o papai."}]'::jsonb,'deduce','Qual é a próxima fala de Heloísa?','["Doggy! My dog is nice.","Look at the rain. God makes the flowers grow.","I like all the colors."]'::jsonb,'Look at the rain. God makes the flowers grow.','Heloísa diz: “Look at the rain. God makes the flowers grow.” — Olhe a chuva. Deus faz as flores crescerem.','en'),
  ('L021:4','L021',4,'[{"who":"arthur","en":"Dad says: obey your parents and listen to your teacher.","pt":"O papai diz: obedeça seus pais e ouça sua professora."},{"who":"noah","en":"Mom, may I play now?","pt":"Mamãe, posso brincar agora?"},{"who":"flavia","en":"First, finish your homework, Noah.","pt":"Primeiro, termine sua lição de casa, Noah."}]'::jsonb,'deduce','Qual é a próxima fala de Noah?','["Yes, Mom. I will obey.","I like all the colors.","Doggy! My dog is nice."]'::jsonb,'Yes, Mom. I will obey.','Noah diz: “Yes, Mom. I will obey.” — Sim, mamãe. Eu vou obedecer.','en'),
  ('L027:1','L027',1,'[{"who":"gael","en":"Dad, yesterday I found a wallet at school.","pt":"Pai, ontem eu achei uma carteira na escola."},{"who":"beto","en":"What did you do with it?","pt":"O que você fez com ela?"},{"who":"gael","en":"I gave it to the teacher. It was not mine.","pt":"Eu a entreguei à professora. Não era minha."}]'::jsonb,'deduce','Qual é a próxima fala de Beto?','["Honesty is the best path, my son. I am proud of you.","Smart choice. Small savings will become a big reward.","It was not mine, Mom. I gave it to the teacher."]'::jsonb,'Honesty is the best path, my son. I am proud of you.','Beto diz: “Honesty is the best path, my son. I am proud of you.” — A honestidade é o melhor caminho, meu filho. Tenho orgulho de você.','en'),
  ('L027:2','L027',2,'[{"who":"gael","en":"Dad, I am going to save my money.","pt":"Pai, eu vou poupar o meu dinheiro."},{"who":"beto","en":"Good. What will you buy?","pt":"Bom. O que você vai comprar?"},{"who":"gael","en":"I will buy a gift for Mom. Saving is better than spending.","pt":"Vou comprar um presente para a mamãe. Poupar é melhor que gastar."}]'::jsonb,'deduce','Qual é a próxima fala de Beto?','["Honesty is the best path, my son. I am proud of you.","It was not mine, Mom. I gave it to the teacher.","Smart choice. Small savings will become a big reward."]'::jsonb,'Smart choice. Small savings will become a big reward.','Beto diz: “Smart choice. Small savings will become a big reward.” — Escolha inteligente. Pequenas economias se tornarão uma grande recompensa.','en'),
  ('L027:3','L027',3,'[{"who":"beto","en":"Yesterday, Gael returned a lost wallet.","pt":"Ontem, o Gael devolveu uma carteira perdida."},{"who":"clara","en":"Honest boy! I am proud of him.","pt":"Menino honesto! Tenho orgulho dele."}]'::jsonb,'deduce','Qual é a próxima fala de Gael?','["Smart choice. Small savings will become a big reward.","It was not mine, Mom. I gave it to the teacher.","Honesty is the best path, my son. I am proud of you."]'::jsonb,'It was not mine, Mom. I gave it to the teacher.','Gael diz: “It was not mine, Mom. I gave it to the teacher.” — Não era minha, mãe. Eu a entreguei à professora.','en'),
  ('L027:4','L027',4,'[{"who":"laura","en":"Daddy, I saved two coins last week!","pt":"Papai, eu guardei duas moedas na semana passada!"},{"who":"beto","en":"Good girl. Small savings will become a big reward.","pt":"Muito bem, filha. Pequenas economias se tornarão uma grande recompensa."}]'::jsonb,'deduce','Qual é a próxima fala de Clara?','["Last Sunday was a happy day for our family.","Honesty is the best path, my son. I am proud of you.","Smart choice. Small savings will become a big reward."]'::jsonb,'Last Sunday was a happy day for our family.','Clara diz: “Last Sunday was a happy day for our family.” — O último domingo foi um dia feliz para a nossa família.','en'),
  ('L053:1','L053',1,'[{"who":"flavia","en":"We have built this company with honest work.","pt":"Nós construímos esta empresa com trabalho honesto."},{"who":"jose","en":"Yes. We have never broken a contract.","pt":"Sim. Nunca quebramos um contrato."},{"who":"flavia","en":"If we keep our word, customers will trust us.","pt":"Se cumprirmos a palavra, os clientes confiarão em nós."}]'::jsonb,'deduce','Qual é a próxima fala de José?','["We must serve them well. That is true leadership.","Exactly. A good deal serves everyone.","Have you checked the delivery schedule?"]'::jsonb,'We must serve them well. That is true leadership.','José diz: “We must serve them well. That is true leadership.” — Devemos servi-los bem. Isso é liderança de verdade.','en'),
  ('L053:2','L053',2,'[{"who":"beatriz","en":"José, have you read the new contract?","pt":"José, você já leu o novo contrato?"},{"who":"jose","en":"Yes. I have read every line. We should sign it.","pt":"Sim. Li cada linha. Deveríamos assiná-lo."},{"who":"beatriz","en":"If the price is fair, both sides will win.","pt":"Se o preço for justo, os dois lados ganharão."}]'::jsonb,'deduce','Qual é a próxima fala de José?','["We must serve them well. That is true leadership.","Have you checked the delivery schedule?","Exactly. A good deal serves everyone."]'::jsonb,'Exactly. A good deal serves everyone.','José diz: “Exactly. A good deal serves everyone.” — Exatamente. Um bom negócio serve a todos.','en'),
  ('L053:3','L053',3,'[{"who":"flavia","en":"We have signed the contract with our new customer.","pt":"Assinamos o contrato com o nosso novo cliente."},{"who":"jose","en":"Excellent. If we deliver on time, they will order again.","pt":"Excelente. Se entregarmos no prazo, eles pedirão de novo."}]'::jsonb,'deduce','Qual é a próxima fala de Beatriz?','["Exactly. A good deal serves everyone.","Have you checked the delivery schedule?","We must serve them well. That is true leadership."]'::jsonb,'Have you checked the delivery schedule?','Beatriz diz: “Have you checked the delivery schedule?” — Você conferiu o cronograma de entrega?','en'),
  ('L053:4','L053',4,'[{"who":"flavia","en":"Yes. I have checked it twice.","pt":"Sim. Conferi duas vezes."},{"who":"jose","en":"Good. A leader should serve the team first.","pt":"Bom. Um líder deve servir à equipe primeiro."}]'::jsonb,'deduce','Qual é a próxima fala de Beatriz?','["And honest profit rewards honest work.","We must serve them well. That is true leadership.","Exactly. A good deal serves everyone."]'::jsonb,'And honest profit rewards honest work.','Beatriz diz: “And honest profit rewards honest work.” — E o lucro honesto recompensa o trabalho honesto.','en'),
  ('L079:1','L079',1,'[{"who":"alice","en":"Our freedoms were protected by brave citizens.","pt":"Nossas liberdades foram protegidas por cidadãos corajosos."},{"who":"lucas","en":"And they must be defended by every generation.","pt":"E devem ser defendidas por cada geração."},{"who":"alice","en":"The law is obeyed here, and justice is served.","pt":"A lei é obedecida aqui, e a justiça é feita."}]'::jsonb,'deduce','Qual é a próxima fala de Lucas?','["Order and liberty are not enemies. They are partners.","Freedom is protected by those who are willing to defend it.","The judge said the trial would begin on Monday."]'::jsonb,'Order and liberty are not enemies. They are partners.','Lucas diz: “Order and liberty are not enemies. They are partners.” — Ordem e liberdade não são inimigas. São parceiras.','en'),
  ('L079:2','L079',2,'[{"who":"lucas","en":"The judge said the law would be respected.","pt":"A juíza disse que a lei seria respeitada."},{"who":"alice","en":"She told us that every citizen had the right to speak.","pt":"Ela nos disse que todo cidadão tinha o direito de falar."},{"who":"lucas","en":"If people had not defended their rights, they would have lost them.","pt":"Se as pessoas não tivessem defendido seus direitos, os teriam perdido."}]'::jsonb,'deduce','Qual é a próxima fala de Alice?','["Order and liberty are not enemies. They are partners.","The judge said the trial would begin on Monday.","Freedom is protected by those who are willing to defend it."]'::jsonb,'Freedom is protected by those who are willing to defend it.','Alice diz: “Freedom is protected by those who are willing to defend it.” — A liberdade é protegida por aqueles que estão dispostos a defendê-la.','en'),
  ('L079:3','L079',3,'[{"who":"alice","en":"Our liberties were won by courageous citizens.","pt":"Nossas liberdades foram conquistadas por cidadãos corajosos."},{"who":"lucas","en":"And they must be defended by every generation.","pt":"E devem ser defendidas por cada geração."}]'::jsonb,'deduce','Qual é a próxima fala de Alice?','["Freedom is protected by those who are willing to defend it.","The judge said the trial would begin on Monday.","Order and liberty are not enemies. They are partners."]'::jsonb,'The judge said the trial would begin on Monday.','Alice diz: “The judge said the trial would begin on Monday.” — A juíza disse que o julgamento começaria na segunda-feira.','en'),
  ('L079:4','L079',4,'[{"who":"lucas","en":"I told her that I would be there as a witness.","pt":"Eu disse a ela que estaria lá como testemunha."},{"who":"alice","en":"If we had stayed silent, justice would have been delayed.","pt":"Se tivéssemos ficado em silêncio, a justiça teria sido adiada."}]'::jsonb,'deduce','Qual é a próxima fala de Lucas?','["Truth must be spoken, even when it costs us.","Order and liberty are not enemies. They are partners.","Freedom is protected by those who are willing to defend it."]'::jsonb,'Truth must be spoken, even when it costs us.','Lucas diz: “Truth must be spoken, even when it costs us.” — A verdade precisa ser dita, mesmo quando nos custa.','en'),
  ('L112:1','L112',1,'[{"who":"ayrton","en":"Rarely does a nation produce such courage.","pt":"Raramente uma nação produz tanta coragem."},{"who":"alice","en":"Not only did they fight bravely, but they also governed wisely.","pt":"Eles não apenas lutaram com bravura, mas também governaram com sabedoria."},{"who":"ayrton","en":"Never have I read a speech so moving.","pt":"Nunca li um discurso tão comovente."}]'::jsonb,'deduce','Qual é a próxima fala de Alice?','["Seldom is truth easy, yet it is always worth defending.","Wisely said. We will proceed with prudence.","I propose that the next meeting be held on Monday."]'::jsonb,'Seldom is truth easy, yet it is always worth defending.','Alice diz: “Seldom is truth easy, yet it is always worth defending.” — Raramente a verdade é fácil, mas ela sempre vale ser defendida.','en'),
  ('L112:2','L112',2,'[{"who":"jose","en":"I propose that the meeting be held on Monday.","pt":"Proponho que a reunião seja realizada na segunda-feira."},{"who":"ayrton","en":"It is essential that every party be heard.","pt":"É essencial que cada parte seja ouvida."},{"who":"jose","en":"Let us not put the cart before the horse. First, the facts.","pt":"Não coloquemos a carroça na frente dos bois. Primeiro, os fatos."}]'::jsonb,'deduce','Qual é a próxima fala de Ayrton?','["Seldom is truth easy, yet it is always worth defending.","I propose that the next meeting be held on Monday.","Wisely said. We will proceed with prudence."]'::jsonb,'Wisely said. We will proceed with prudence.','Ayrton diz: “Wisely said. We will proceed with prudence.” — Bem dito. Prosseguiremos com prudência.','en'),
  ('L112:3','L112',3,'[{"who":"ayrton","en":"Rarely does a nation produce such courage.","pt":"Raramente uma nação produz tanta coragem."},{"who":"alice","en":"Not only did they fight bravely, but they also governed wisely.","pt":"Eles não apenas lutaram com bravura, mas também governaram com sabedoria."}]'::jsonb,'deduce','Qual é a próxima fala de José?','["Wisely said. We will proceed with prudence.","I propose that the next meeting be held on Monday.","Seldom is truth easy, yet it is always worth defending."]'::jsonb,'I propose that the next meeting be held on Monday.','José diz: “I propose that the next meeting be held on Monday.” — Proponho que a próxima reunião seja realizada na segunda-feira.','en'),
  ('L112:4','L112',4,'[{"who":"ayrton","en":"It is essential that every party be heard.","pt":"É essencial que cada parte seja ouvida."},{"who":"jose","en":"Let us not put the cart before the horse.","pt":"Não coloquemos a carroça na frente dos bois."}]'::jsonb,'deduce','Qual é a próxima fala de Alice?','["Wisely said. First the facts, then the decision.","Seldom is truth easy, yet it is always worth defending.","Wisely said. We will proceed with prudence."]'::jsonb,'Wisely said. First the facts, then the decision.','Alice diz: “Wisely said. First the facts, then the decision.” — Bem dito. Primeiro os fatos, depois a decisão.','en');
insert into roleplays (level_id,character_id,ask,ask_pt,model,model_pt,accept) values
  ('L001','ayrton','Good morning! How are you?','Bom dia! Como vai?','I am fine, thank you. And you?','Estou bem, obrigado. E você?','["I am fine, thank you. And you?","I am fine, thank you.","Good morning! I am fine, thank you. And you?","I am fine, thanks. And you?"]'::jsonb),
  ('L002','ayrton','What time does our meeting start?','A que horas começa a nossa reunião?','Our meeting starts at nine o''clock.','Nossa reunião começa às nove horas.','["Our meeting starts at nine o''clock.","The meeting starts at nine o''clock."]'::jsonb),
  ('L006','maria','Would you like some soup?','O senhor aceita um pouco de sopa?','Yes, please. Thank you very much.','Sim, por favor. Muito obrigado.','["Yes, please. Thank you very much.","Yes, please. Thank you."]'::jsonb),
  ('L011','jose','What time do you start work?','A que horas você começa a trabalhar?','I start work at seven o''clock.','Eu começo a trabalhar às sete horas.','["I start work at seven o''clock.","I start work at seven."]'::jsonb),
  ('L016','lucas','Where is the library?','Onde fica a biblioteca?','The library is next to the church.','A biblioteca fica ao lado da igreja.','["The library is next to the church.","It is next to the church."]'::jsonb),
  ('L017','beto','What do you do on Sunday?','O que você faz no domingo?','On Sunday, we go to church with our family.','No domingo, vamos à igreja com a nossa família.','["On Sunday, we go to church with our family.","On Sunday I go to church with my family."]'::jsonb),
  ('L021','theo','What color is the dog?','De que cor é o cachorro?','The dog is brown.','O cachorro é marrom.','["The dog is brown.","It is brown."]'::jsonb),
  ('L027','beto','What did you do yesterday?','O que você fez ontem?','Yesterday I found a wallet and returned it.','Ontem achei uma carteira e a devolvi.','["Yesterday I found a wallet and returned it.","Yesterday I returned a wallet."]'::jsonb),
  ('L053','jose','Have you read the contract?','Você leu o contrato?','Yes, I have read the contract.','Sim, li o contrato.','["Yes, I have read the contract.","Yes, I have read it."]'::jsonb),
  ('L079','alice','What must every generation do?','O que cada geração deve fazer?','Every generation must defend freedom.','Cada geração deve defender a liberdade.','["Every generation must defend freedom.","Every generation must defend our freedom."]'::jsonb),
  ('L112','jose','When shall we hold the meeting?','Quando devemos realizar a reunião?','I suggest that we hold it on Monday.','Sugiro que a realizemos na segunda-feira.','["I suggest that we hold it on Monday.","I propose that we hold it on Monday."]'::jsonb);
